        _fail(f"基因集文件不是合法的 UTF-8 文本：{path}")

    # splitlines 兼容 \n 与 \r\n，且不会因末尾换行产生空行
    lines = text.splitlines()
    if not lines:
        _fail("基因集表头缺失：文件为空")
