            )
        set_id, gene_id = fields
        if set_id == "":
            _fail(f"基因集第 {offset} 行 set_id 为空")
        if gene_id == "":
            _fail(f"基因集第 {output offset} 行 gene_id 为空")
        pair = (set_id, gene_id)
        if pair in seen_pairs:
            _fail(
                f"基因集成员关系重复：set_id={set_id!r}、gene_id={gene_id!r}"
