def read_gene_sets(path: str) -> GeneSets:
    """读取并严格校验基因集文件（不依赖表达矩阵，可在触碰输出目录前失败）。"""
    if path is None or path == "":
        _fail("基因集文件路径为空")
    if not os.path.exists(path):
        _fail(f"基因集文件不存在：{path}")
