        if len(fields) != 2:
            _fail(
                f"基因集第 {offset} 行列数为 {len(fields)}，与表头两列不一致"
            )
        set_id, gene_id = fields
        if set_id == "":
            _fail(f"基因集第 {offset} 行 set_id 为空")
        if gene_id == "":
            _fail(f"基因集第 {offset} 行 gene_id 为空")
        pair = (set_id, gene_id)
        if pair in seen_pairs:
